// testDeps matches the fakeplugin's cookie pair.
func testDeps() Deps {
	return Deps{
		MagicCookieKey:   "MELLIFERA_TEST_COOKIE",
		MagicCookieValue: "test-secret",
		CoreVersion:      "0.1.0",
	}
}

func scannerCap(id string) []sdk.Capability {
	return []sdk.Capability{{Type: "scanner", ID: id, ProtoService: "mellifera.scanner.v1.Scanner"}}
}

func metadataCap(id string) []sdk.Capability {
	return []sdk.Capability{{Type: "metadata_source", ID: id, ProtoService: "mellifera.metadata.v1.MetadataSource"}}
}

// buildFakePlugin builds the testdata subprocess to a temp binary. go test runs
// the test binary with cwd = this package dir, so ./testdata/fakeplugin (via the
// internal/plugin prefix) resolves. The explicit-path build is not skipped by
// the testdata rule (only ./... matching is).
func buildFakePlugin(t *testing.T) string {
	t.Helper()
	out := filepath.Join(t.TempDir(), "fakeplugin")
	cmd := exec.Command("go", "build", "-o", out, "./testdata/fakeplugin")
	cmd.Env = append(os.Environ(), "CGO_ENABLED=0")
	if b, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("build fakeplugin: %v\n%s", err, b)
	}
	return out
}

