func TestOpen(t *testing.T) {
	m := Open(testDeps())
	if m == nil {
		t.Fatal("Open returned nil")
	}
	if m.launchFn == nil || m.backoff == nil || m.pollInterval == 0 || m.now == nil {
		t.Fatal("Open did not wire production defaults (launch/backoff/poll/now)")
	}
}

func TestLoad(t *testing.T) {
	tests := []struct {
		name    string
		id      string
		binary  string
		preload bool
		wantErr bool
	}{
		{name: "ok", id: "p", binary: "/bin/true"},
		{name: "empty id", id: "", binary: "/bin/true", wantErr: true},
		{name: "empty path", id: "p", binary: "", wantErr: true},
		{name: "duplicate", id: "p", binary: "/bin/true", preload: true, wantErr: true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			m := Open(testDeps())
			if tc.preload {
				if err := m.Load("p", "/bin/true", nil); err != nil {
					t.Fatalf("preload: %v", err)
				}
			}
			err := m.Load(tc.id, tc.binary, scannerCap("default"))
			if (err != nil) != tc.wantErr {
				t.Fatalf("Load err=%v, wantErr=%v", err, tc.wantErr)
			}
			if !tc.wantErr && err == nil {
				if h, err := m.Status(tc.id); err != nil || h.State != stateNotServing {
					t.Fatalf("loaded plugin should be not_serving, got %+v err=%v", h, err)
				}
			}
		})
	}
}

func TestScanner_AccessorErrors(t *testing.T) {
	// "serving" entry reached without a subprocess via an injected fake launch.
	serving := Open(testDeps())
	serving.launchFn = func(context.Context, *pluginEntry) (*runningPlugin, error) {
		return &runningPlugin{scanner: mockScanner{}, pconn: fakePluginClient{}, exited: func() bool { return false }, kill: func() {}}, nil
	}
	if err := serving.Load("up", "/bin/true", scannerCap("default")); err != nil {
		t.Fatal(err)
	}
	if err := serving.Start(context.Background(), "up"); err != nil {
		t.Fatalf("Start: %v", err)
	}
	t.Cleanup(func() { _ = serving.Stop(context.Background(), "up") })

	notStarted := Open(testDeps())
	_ = notStarted.Load("loaded", "/bin/true", scannerCap("default"))

	tests := []struct {
		name    string
		m       *Manager
		plugin  string
		cap     string
		wantErr string
	}{
		{name: "not loaded", m: serving, plugin: "nope", cap: "default", wantErr: "not loaded"},
		{name: "not serving", m: notStarted, plugin: "loaded", cap: "default", wantErr: "not serving"},
		{name: "unknown capability", m: serving, plugin: "up", cap: "missing", wantErr: "not declared"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			sc, err := tc.m.Scanner(tc.plugin, tc.cap)
			if err == nil {
				t.Fatalf("Scanner: expected error, got %v", sc)
			}
			if !strings.Contains(err.Error(), tc.wantErr) {
				t.Fatalf("Scanner err=%q, want substring %q", err.Error(), tc.wantErr)
			}
		})
	}

	// Positive accessor: the typed client comes back and implements sdk.Scanner.
	sc, err := serving.Scanner("up", "default")
	if err != nil {
		t.Fatalf("Scanner(up,default): %v", err)
	}
	var _ sdk.Scanner = sc
}

// TestManager_RoundTrip proves seam S5 + AC-1 + B8 against a REAL go-plugin
// subprocess: magic-cookie substrate handshake, gRPC dial, domain Handshake,
// the typed Scanner streams + identifies, Status reports serving, Stop shuts
// the subprocess down cleanly.
func TestManager_RoundTrip(t *testing.T) {
	bin := buildFakePlugin(t)
	m := Open(testDeps())
	if err := m.Load("fake", bin, scannerCap("default")); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = m.Stop(context.Background(), "fake") })

	ctx := context.Background()
	if err := m.Start(ctx, "fake"); err != nil {
		t.Fatalf("Start: %v", err)
	}
	if h, _ := m.Status("fake"); h.State != stateServing {
		t.Fatalf("after Start, state=%+v, want serving", h)
	}

	sc, err := m.Scanner("fake", "default")
	if err != nil {
		t.Fatalf("Scanner: %v", err)
	}

	ss, err := sc.Scan(ctx, &scannerv1.ScanRequest{LibraryPath: ".", ModuleType: "tv"})
	if err != nil {
		t.Fatalf("Scan: %v", err)
	}
	var files []*scannerv1.DiscoveredFile
	for f := range ss.Files {
		files = append(files, f)
	}
	if len(files) != 2 {
		t.Fatalf("Scan streamed %d files, want 2", len(files))
	}
	if files[0].GetFileId() != "f1" || len(files[0].GetFfprobeJson()) == 0 {
		t.Fatalf("first file = %+v, want file_id=f1 with ffprobe bytes", files[0])
	}
	if files[1].GetFileId() != "f2" {
		t.Fatalf("second file_id = %q, want f2", files[1].GetFileId())
	}

	id, err := sc.Identify(ctx, &scannerv1.IdentifyRequest{File: files[0], ModuleType: "tv"})
	if err != nil {
		t.Fatalf("Identify: %v", err)
	}
	if id.GetFileId() != "f1" || id.GetParserName() != "fake" {
		t.Fatalf("Identify = %+v, want file_id=f1 parser=fake", id)
	}

	if err := m.Stop(ctx, "fake"); err != nil {
		t.Fatalf("Stop: %v", err)
	}
	if h, _ := m.Status("fake"); h.State != stateNotServing || h.Message != "stopped" {
		t.Fatalf("after Stop, health=%+v, want state=not_serving msg=stopped", h)
	}
}

// TestManager_RestartFailedAfterThree proves B7 / §7.3 deterministically: a
// serving plugin that exits unexpectedly is restarted with backoff, and after 3
// consecutive failed restarts it is marked failed. A real-subprocess crash test
// would be flaky; the injected launchFn drives the state machine directly.
func TestManager_RestartFailedAfterThree(t *testing.T) {
	m := Open(testDeps())
	if err := m.Load("p", "/bin/true", scannerCap("default")); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = m.Stop(context.Background(), "p") })

	var crashed int32
	launched := false
	m.launchFn = func(context.Context, *pluginEntry) (*runningPlugin, error) {
		if !launched { // initial Start succeeds
			launched = true
			return &runningPlugin{
				scanner: mockScanner{},
				pconn:   fakePluginClient{},
				exited:  func() bool { return atomic.LoadInt32(&crashed) != 0 },
				kill:    func() {},
			}, nil
		}
		return nil, errors.New("restart boom") // every restart fails
	}
	m.backoff = func(int) time.Duration { return time.Millisecond }
	m.pollInterval = time.Millisecond

	if err := m.Start(context.Background(), "p"); err != nil {
		t.Fatalf("Start: %v", err)
	}
	if h, _ := m.Status("p"); h.State != stateServing {
		t.Fatalf("pre-crash state=%+v, want serving", h)
	}
	atomic.StoreInt32(&crashed, 1) // simulate unexpected exit

	deadline := time.Now().Add(3 * time.Second)
	var h Health
	for time.Now().Before(deadline) {
		h, _ = m.Status("p")
		if h.State == stateFailed {
			break
		}
		time.Sleep(time.Millisecond)
	}
	if h.State != stateFailed {
		t.Fatalf("state=%q after crash, want failed (restarts=%d)", h.State, h.Restarts)
	}
	if h.Restarts != maxRestarts {
		t.Fatalf("restarts=%d, want %d", h.Restarts, maxRestarts)
	}
}

func TestExponentialBackoff(t *testing.T) {
	tests := []struct {
		attempt int
		lo      time.Duration // base (no jitter)
		hi      time.Duration // base + 25% jitter ceiling
	}{
		{attempt: 0, lo: 1 * time.Second, hi: 1250 * time.Millisecond},
		{attempt: 1, lo: 2 * time.Second, hi: 2500 * time.Millisecond},
		{attempt: 2, lo: 4 * time.Second, hi: 5 * time.Second},
		{attempt: 10, lo: 60 * time.Second, hi: 75 * time.Second}, // capped
	}
	for _, tc := range tests {
		t.Run("attempt", func(t *testing.T) {
			d := exponentialBackoff(tc.attempt)
			if d < tc.lo || d > tc.hi {
				t.Fatalf("backoff(%d)=%s, want [%s,%s]", tc.attempt, d, tc.lo, tc.hi)
			}
		})
	}
}

// TestMetadataSource_Accessor mirrors TestScanner_AccessorErrors for the
// metadata_source capability: error rows for not-loaded / not-serving /
// cap-not-declared, plus the scanner-only-plugin case (MetadataSource must
// reject a plugin that declared only scanner — INV-ac3 / seam S2), and a
// positive accessor returning the typed client.
func TestMetadataSource_Accessor(t *testing.T) {
	serving := Open(testDeps())
	serving.launchFn = func(context.Context, *pluginEntry) (*runningPlugin, error) {
		return &runningPlugin{metadata: mockMetadata{}, pconn: fakePluginClient{}, exited: func() bool { return false }, kill: func() {}}, nil
	}
	if err := serving.Load("up", "/bin/true", metadataCap("default")); err != nil {
		t.Fatal(err)
	}
	if err := serving.Start(context.Background(), "up"); err != nil {
		t.Fatalf("Start: %v", err)
	}
	t.Cleanup(func() { _ = serving.Stop(context.Background(), "up") })

	notStarted := Open(testDeps())
	_ = notStarted.Load("loaded", "/bin/true", metadataCap("default"))

	// A scanner-only serving plugin: MetadataSource must error "not declared".
	scannerOnly := Open(testDeps())
	scannerOnly.launchFn = func(context.Context, *pluginEntry) (*runningPlugin, error) {
		return &runningPlugin{scanner: mockScanner{}, pconn: fakePluginClient{}, exited: func() bool { return false }, kill: func() {}}, nil
	}
	if err := scannerOnly.Load("scan", "/bin/true", scannerCap("default")); err != nil {
		t.Fatal(err)
	}
	if err := scannerOnly.Start(context.Background(), "scan"); err != nil {
		t.Fatalf("Start scan: %v", err)
	}
	t.Cleanup(func() { _ = scannerOnly.Stop(context.Background(), "scan") })

	tests := []struct {
		name    string
		m       *Manager
		plugin  string
		cap     string
		wantErr string
	}{
		{name: "not loaded", m: serving, plugin: "nope", cap: "default", wantErr: "not loaded"},
		{name: "not serving", m: notStarted, plugin: "loaded", cap: "default", wantErr: "not serving"},
		{name: "unknown capability", m: serving, plugin: "up", cap: "missing", wantErr: "not declared"},
		{name: "scanner-only plugin", m: scannerOnly, plugin: "scan", cap: "default", wantErr: "not declared"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			md, err := tc.m.MetadataSource(tc.plugin, tc.cap)
			if err == nil {
				t.Fatalf("MetadataSource: expected error, got %v", md)
			}
			if !strings.Contains(err.Error(), tc.wantErr) {
				t.Fatalf("MetadataSource err=%q, want substring %q", err.Error(), tc.wantErr)
			}
		})
	}

	// Positive accessor: the typed client comes back and implements sdk.MetadataSource.
	md, err := serving.MetadataSource("up", "default")
	if err != nil {
		t.Fatalf("MetadataSource(up,default): %v", err)
	}
	var _ sdk.MetadataSource = md
}

// TestClientPluginSet proves B2/INV-caps-driven/INV-ac3-base-scanner: the
// client PluginSet is built ONLY from declared capabilities, one adapter per
// type, and base-scanner's scanner-only set is byte-for-byte {scanner: ScannerPlugin{}}.
func TestClientPluginSet(t *testing.T) {
	scannerOnly := scannerCap("default")
	metaOnly := metadataCap("default")
	both := []sdk.Capability{
		{Type: "scanner", ID: "default"},
		{Type: "metadata_source", ID: "default"},
	}
	tests := []struct {
		name string
		caps []sdk.Capability
		want []string
	}{
		{name: "scanner only (base-scanner)", caps: scannerOnly, want: []string{scannerPluginKey}},
		{name: "metadata only (tv-parser)", caps: metaOnly, want: []string{metadataSourcePluginKey}},
		{name: "both capabilities", caps: both, want: []string{scannerPluginKey, metadataSourcePluginKey}},
		{name: "unknown type omitted", caps: []sdk.Capability{{Type: "future-cap", ID: "x"}}, want: nil},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			set := clientPluginSet(tc.caps)
			if len(set) != len(tc.want) {
				t.Fatalf("clientPluginSet = %d entries %v, want %d %v", len(set), set, len(tc.want), tc.want)
			}
			for _, k := range tc.want {
				if _, ok := set[k]; !ok {
					t.Errorf("clientPluginSet missing key %q (got %v)", k, set)
				}
			}
		})
	}

	// INV-ac3: base-scanner's set is exactly {scanner: *sdk.ScannerPlugin}.
	base := clientPluginSet(scannerOnly)
	if len(base) != 1 {
		t.Fatalf("base-scanner set has %d entries, want 1 (%v)", len(base), base)
	}
	if _, ok := base[scannerPluginKey].(*sdk.ScannerPlugin); !ok {
		t.Fatalf("base-scanner set[scanner] = %T, want *sdk.ScannerPlugin", base[scannerPluginKey])
	}

	// metadata_source adapter type check (tv-parser dispense target).
	meta := clientPluginSet(metaOnly)
	if _, ok := meta[metadataSourcePluginKey].(*sdk.MetadataSourcePlugin); !ok {
		t.Fatalf("tv-parser set[metadata_source] = %T, want *sdk.MetadataSourcePlugin", meta[metadataSourcePluginKey])
	}
}
